// Same build, same user, two runs on .NET 10:
// run 1: "u-00042".GetHashCode() = 1047013002   -> new checkout
// run 2: "u-00042".GetHashCode() = -1043018878  -> old checkout

using System.Security.Cryptography;
using System.Text;

// Owner and removal date travel with the flag
public record Flag(string Name, int Percent, string Owner, DateOnly RemoveBy);

public class FeatureDecisions(Flag newCheckout)
{
    // One named decision per feature; toggle points only call this
    public bool UseNewCheckout(string userId) => InRollout(newCheckout, userId);

    static bool InRollout(Flag flag, string userId)
    {
        // Same bucket (0-99) for this user and flag in every process
        var key = Encoding.UTF8.GetBytes($"{flag.Name}:{userId}");
        var bucket = BitConverter.ToUInt32(SHA256.HashData(key)) % 100;
        return bucket < flag.Percent;
    }
}
